CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY, parent TEXT REFERENCES posts(id), topic TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, owner TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY, post TEXT NOT NULL REFERENCES posts(id), reason TEXT NOT NULL, reporter TEXT NOT NULL, created INTEGER NOT NULL, resolved INTEGER NOT NULL DEFAULT 0, UNIQUE(post,reporter));
CREATE TABLE IF NOT EXISTS limits(bucket TEXT PRIMARY KEY, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS config(key TEXT PRIMARY KEY,value TEXT NOT NULL);
